//! `#[tool]` on functions.

use darling::FromMeta;
use darling::ast::NestedMeta;
use proc_macro2::{Span, TokenStream};
use quote::{format_ident, quote};
use syn::spanned::Spanned;
use syn::{Attribute, FnArg, Ident, ItemFn, Pat, ReturnType, Type, Visibility};

#[allow(clippy::unreachable, reason = "generated by the darling derive")]
mod args {
    use darling::FromMeta;
    use darling::util::Flag;

    /// `#[tool(..)]` on a function or method.
    #[derive(Debug, Default, FromMeta)]
    pub(crate) struct ToolArgs {
        pub(crate) name: Option<String>,
    }

    /// `#[tool(..)]` on a parameter.
    #[derive(Debug, Default, FromMeta)]
    pub(crate) struct ParamArgs {
        pub(crate) context: Flag,
    }
}

use args::ParamArgs;
pub(crate) use args::ToolArgs;

/// A parsed tool function, shared by `#[tool]` and `#[tools]`.
pub(crate) struct ToolFn {
    pub(crate) name: String,
    pub(crate) description: String,
    pub(crate) ident: Ident,
    pub(crate) is_async: bool,
    pub(crate) has_receiver: bool,
    params: Vec<Param>,
    context_index: Option<usize>,
    returns_result: bool,
}

struct Param {
    ident: Ident,
    ty: Type,
    doc: Option<String>,
}

pub(crate) fn parse_args(attr: TokenStream) -> syn::Result<ToolArgs> {
    let items = NestedMeta::parse_meta_list(attr)?;
    ToolArgs::from_list(&items).map_err(|error| syn::Error::new(Span::call_site(), error.to_string()))
}

/// Joins `///` lines the way TS reads a `JSDoc` description: trimmed lines joined by newlines.
pub(crate) fn doc_text(attrs: &[Attribute]) -> Option<String> {
    let lines: Vec<String> = attrs
        .iter()
        .filter(|attr| attr.path().is_ident("doc"))
        .filter_map(|attr| match &attr.meta {
            syn::Meta::NameValue(syn::MetaNameValue {
                value:
                    syn::Expr::Lit(syn::ExprLit {
                        lit: syn::Lit::Str(text),
                        ..
                    }),
                ..
            }) => Some(text.value().trim().to_owned()),
            _ => None,
        })
        .collect();
    let text = lines.join("\n").trim().to_owned();
    (!text.is_empty()).then_some(text)
}

fn is_valid_name(name: &str) -> bool {
    !name.is_empty()
        && name.len() <= 64
        && name
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-')
}

pub(crate) fn pascal_case(name: &str) -> String {
    name.split('_')
        .filter(|part| !part.is_empty())
        .map(|part| {
            let mut chars = part.chars();
            chars
                .next()
                .map_or_else(String::new, |first| first.to_uppercase().chain(chars).collect())
        })
        .collect()
}

fn returns_result(output: &ReturnType) -> bool {
    let ReturnType::Type(_, ty) = output else {
        return false;
    };
    let Type::Path(path) = ty.as_ref() else {
        return false;
    };
    path.path
        .segments
        .last()
        .is_some_and(|segment| segment.ident == "Result")
}

impl ToolFn {
    /// Parses `item` and strips the parameter attributes rustc would reject after expansion.
    pub(crate) fn parse(item: &mut ItemFn, args: ToolArgs) -> syn::Result<Self> {
        let sig = &item.sig;
        if !sig.generics.params.is_empty() {
            return Err(syn::Error::new(
                sig.generics.span(),
                "#[tool] functions can't be generic",
            ));
        }
        let name = args.name.unwrap_or_else(|| sig.ident.to_string());
        if !is_valid_name(&name) {
            return Err(syn::Error::new(
                sig.ident.span(),
                format!("tool name '{name}' must be 1 to 64 characters of [a-zA-Z0-9_-]"),
            ));
        }
        let Some(description) = doc_text(&item.attrs) else {
            return Err(syn::Error::new(
                sig.ident.span(),
                "#[tool] needs a doc comment: it is the tool description the model sees",
            ));
        };
        let ident = sig.ident.clone();
        let is_async = sig.asyncness.is_some();
        let returns_result = returns_result(&sig.output);
        let mut params = Vec::new();
        let mut context_index = None;
        let mut has_receiver = false;
        for (index, input) in item.sig.inputs.iter_mut().enumerate() {
            match input {
                FnArg::Receiver(receiver) => {
                    let by_ref = matches!(receiver.kind, syn::ReceiverKind::Reference(_, _, None));
                    if !by_ref || receiver.mutability.is_some() {
                        return Err(syn::Error::new(receiver.span(), "#[tool] methods take `&self`"));
                    }
                    has_receiver = true;
                }
                FnArg::Typed(typed) => {
                    let mut is_context = false;
                    for attr in typed.attrs.iter().filter(|attr| attr.path().is_ident("tool")) {
                        let nested = NestedMeta::parse_meta_list(attr.meta.require_list()?.tokens.clone())?;
                        let parsed = ParamArgs::from_list(&nested)
                            .map_err(|error| syn::Error::new(attr.span(), error.to_string()))?;
                        is_context |= parsed.context.is_present();
                    }
                    let doc = doc_text(&typed.attrs);
                    typed
                        .attrs
                        .retain(|attr| !attr.path().is_ident("doc") && !attr.path().is_ident("tool"));
                    if is_context {
                        if context_index.is_some() {
                            return Err(syn::Error::new(
                                typed.span(),
                                "only one parameter can be #[tool(context)]",
                            ));
                        }
                        context_index = Some(index);
                        continue;
                    }
                    let Pat::Ident(pat) = typed.pat.as_ref() else {
                        return Err(syn::Error::new(
                            typed.pat.span(),
                            "#[tool] parameters must be plain names",
                        ));
                    };
                    params.push(Param {
                        ident: pat.ident.clone(),
                        ty: typed.ty.as_ref().clone(),
                        doc,
                    });
                }
            }
        }
        Ok(Self {
            name,
            description,
            ident,
            is_async,
            has_receiver,
            params,
            context_index,
            returns_result,
        })
    }

    /// `impl Tool for <tool_type>`; `this` reaches the receiver for methods.
    pub(crate) fn impl_tool(&self, tool_type: &TokenStream, call_path: &TokenStream) -> TokenStream {
        let name = &self.name;
        let description = &self.description;
        let input = format_ident!("__StrandsToolInput");
        let fields = self.params.iter().map(|param| {
            let ident = &param.ident;
            let ty = &param.ty;
            let doc = param.doc.as_ref().map(|doc| quote!(#[doc = #doc]));
            quote! { #doc #ident: #ty, }
        });
        let field_names: Vec<&Ident> = self.params.iter().map(|param| &param.ident).collect();
        let mut args: Vec<TokenStream> = field_names.iter().map(|ident| quote!(input.#ident)).collect();
        if let Some(index) = self.context_index {
            let index = index.saturating_sub(usize::from(self.has_receiver));
            args.insert(index.min(args.len()), quote!(&context));
        }
        let receiver = self.has_receiver.then(|| quote!(this.));
        let call = if self.has_receiver {
            quote!(#receiver #call_path(#(#args),*))
        } else {
            quote!(#call_path(#(#args),*))
        };
        let wrap = if self.returns_result {
            quote! {
                match output {
                    ::core::result::Result::Ok(value) => ::strands::__private::to_outcome(&value, &tool_use_id),
                    ::core::result::Result::Err(error) => {
                        ::strands::ToolError::from(error).into_outcome(&tool_use_id)
                    }
                }
            }
        } else {
            quote!(::strands::__private::to_outcome(&output, &tool_use_id))
        };
        let run = if self.is_async {
            quote! {
                let output = #call.await;
                #wrap
            }
        } else {
            quote! {
                let blocking_id = tool_use_id.clone();
                let joined = ::strands::__private::tokio::task::spawn_blocking(move || {
                    let tool_use_id = blocking_id;
                    let output = #call;
                    #wrap
                })
                .await;
                ::strands::__private::joined_outcome(joined, &tool_use_id)
            }
        };
        let clone_this = self
            .has_receiver
            .then(|| quote!(let this = ::std::sync::Arc::clone(&self.0);));
        quote! {
            #[derive(::strands::__private::serde::Deserialize, ::strands::__private::schemars::JsonSchema)]
            #[serde(crate = "::strands::__private::serde")]
            #[schemars(crate = "::strands::__private::schemars")]
            struct #input {
                #(#fields)*
            }

            impl ::strands::Tool for #tool_type {
                fn name(&self) -> &str {
                    #name
                }

                fn description(&self) -> &str {
                    #description
                }

                fn tool_spec(&self) -> ::strands::tools::ToolSpec {
                    ::strands::tools::ToolSpec::new(#name, #description)
                        .with_input_schema(::strands::tools::schema_for::<#input>())
                }

                fn stream(&self, context: ::strands::ToolContext) -> ::strands::tools::ToolStream {
                    #clone_this
                    ::strands::tools::ToolStream::from_future(async move {
                        let tool_use_id = context.tool_use().tool_use_id.clone();
                        let schema = ::strands::tools::schema_for::<#input>();
                        let validator = ::strands::tools::InputValidator::new(&schema);
                        let input: #input = match validator.parse(context.tool_use().input.clone()) {
                            ::core::result::Result::Ok(input) => input,
                            ::core::result::Result::Err(error) => return error.into_outcome(&tool_use_id),
                        };
                        #run
                    })
                }
            }
        }
    }
}

pub(crate) fn expand(attr: TokenStream, item: TokenStream) -> syn::Result<TokenStream> {
    let args = parse_args(attr)?;
    let mut item: ItemFn = syn::parse2(item)?;
    let tool = ToolFn::parse(&mut item, args)?;
    if tool.has_receiver {
        return Err(syn::Error::new(
            item.sig.ident.span(),
            "#[tool] on a method needs #[tools] on the impl block",
        ));
    }
    let struct_ident = Ident::new(&pascal_case(&tool.ident.to_string()), tool.ident.span());
    let vis: &Visibility = &item.vis;
    let docs: Vec<&Attribute> = item
        .attrs
        .iter()
        .filter(|attr| attr.path().is_ident("doc"))
        .collect();
    let fn_ident = &tool.ident;
    let tool_impl = tool.impl_tool(&quote!(#struct_ident), &quote!(#fn_ident));
    Ok(quote! {
        #item

        #(#docs)*
        #[derive(Debug, Clone, Copy, Default)]
        #vis struct #struct_ident;

        const _: () = {
            #tool_impl
        };
    })
}
